fn end(&mut self, tag: TagEnd, width: usize) {
    match tag {
        TagEnd::Strong => self.bold = self.bold.saturating_sub(1),
        TagEnd::Emphasis => self.italic = self.italic.saturating_sub(1),
        TagEnd::Strikethrough => self.strike = self.strike.saturating_sub(1),
        TagEnd::CodeBlock => {
            self.flush();
            self.code = false;
            self.blank();
        }
        TagEnd::List(_) => {
            self.flush();
            self.lists.pop();
            self.indent = self.lists.len() * 2;
            self.blank();
        }
        TagEnd::Item => self.flush(),
        TagEnd::BlockQuote(_) => {
            self.flush();
            self.quote = self.quote.saturating_sub(1);
        }
        TagEnd::Heading(_) => {
            self.flush();
            self.bold = self.bold.saturating_sub(1);
            self.blank();
        }
        TagEnd::Paragraph => self.flush(),
        TagEnd::Link => {
            if let Some(url) = self.link.take() {
                let text: String = self.spans.iter().map(|span| span.text.as_str()).collect();
                if !url.starts_with('#') && url != text {
                    self.push(Ink::Dim, &format!(" ({url})"));
                }
            }
        }
        TagEnd::TableCell => {
            let text: String = self.spans.iter().map(|span| span.text.as_str()).collect();
            self.cells.push(text.trim().to_string());
            self.spans.clear();
        }
        TagEnd::TableRow | TagEnd::TableHead => self.end_row(),
        TagEnd::Table => {
            self.in_table = false;
            self.blocks.push(Block {
                indent: self.indent,
                spans: vec![Span {
                    ink: Ink::Dim,
                    text: "─".repeat(width.min(48)),
                }],
                code: false,
            });
        }
        _ => {}
    }
}

fn end_row(&mut self) {
    if self.cells.is_empty() {
        return;
    }
    let mut spans = Vec::new();
    for (index, cell) in self.cells.drain(..).enumerate() {
        if index > 0 {
            spans.push(Span {
                ink: Ink::Dim,
                text: " │ ".into(),
            });
        }
        spans.push(Span {
            ink: Ink::Plain,
            text: cell,
        });
    }
    self.blocks.push(Block {
        indent: self.indent,
        spans,
        code: false,
    });
}
